import torch, sys, types, collections, heapq
class Maze(torch.nn.Module):
    def __init__(self):
        super().__init__()
sys.modules['__main__'].Maze = Maze
obj = torch.load('/work/maze.pt', map_location='cpu', weights_only=False)
W = obj.maze.weight.detach().cpu().numpy().astype(int)
N = W.shape[0]
adj = {i: [j for j in range(N) if W[i][j]!=0] for i in range(N)}
# BFS
start, goal = 2, 3
from collections import deque
prev = {start: None}
queue = deque([start])
while queue:
    u = queue.popleft()
    if u == goal:
        break
    for v in adj[u]:
        if v not in prev:
            prev[v] = u
            queue.append(v)
# reconstruct path
if goal not in prev:
    print('no path')
else:
    path = []
    cur = goal
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path = list(reversed(path))
    print('path:', path)
    # produce string representation maybe as numbers separated by ->
    print('path string:', '-'.join(map(str,path)))

